contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        require(c.totalSupply() == 0);
        bool reverted;
        try c.buyShares(to) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.totalSupply() == 0 && c.balanceOf(to) == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address owner, address spender, uint256 value) public {
        require(true);

        uint256 nonceBefore = c.nonces(owner);
        uint256 allowanceBefore = c.allowance(owner, spender);
        uint256 deadline = block.timestamp + 100;

        // signature bytes are all zero, so ecrecover cannot recover `owner`:
        // permit must revert with DODO_DSP_LP: INVALID_SIGNATURE.
        bool reverted;
        try c.permit(owner, spender, value, deadline, 27, bytes32(0), bytes32(0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 nonceAfter = c.nonces(owner);
        uint256 allowanceAfter = c.allowance(owner, spender);

        assert(
            reverted &&
            nonceAfter == nonceBefore + 1 &&
            allowanceAfter == allowanceBefore
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 priceLimit) public {
        require(priceLimit <= 1e6);
        uint256 before = c._PRICE_LIMIT_();
        bool reverted;
        try c.adjustPriceLimit(priceLimit) { reverted = false; } catch { reverted = true; }
        uint256 after_ = c._PRICE_LIMIT_();
        assert(reverted && after_ == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 shareAmount) public {
        uint256 totalSupplyBefore = c.totalSupply();
        bool reverted;
        try c.sellShares(shareAmount, address(this), 0, 0, "", 0) { reverted = false; } catch { reverted = true; }
        uint256 totalSupplyAfter = c.totalSupply();
        assert(reverted && totalSupplyAfter == totalSupplyBefore);
    }
    receive() external payable {}
}
